pub(crate) const EDITOR_SEED_MARKER: &str = "⟦Editor⟧ ";

/// 1.2.21+ — one-line framing prepended to the seeded Facts user turn.
pub(crate) fn facts_seed_intro(lang_iso: &str) -> &'static str {
    match lang_iso {
        "ru" => "Установленные факты мира — считай их истиной при проверке этой рукописи:",
        "de" => "Etablierte Weltfakten — behandle sie als Grundwahrheit bei der Faktenprüfung dieses Manuskripts:",
        "fr" => "Faits établis du monde — considère-les comme la vérité de référence pour vérifier ce manuscrit :",
        "es" => "Hechos establecidos del mundo — trátalos como verdad de referencia al verificar este manuscrito:",
        _ => "Established world facts — treat these as ground truth when fact-checking this manuscript:",
    }
}

/// 1.2.21+ — the seeded assistant acknowledgement that follows the
/// facts in the Facts-scope chat prologue.
pub(crate) fn facts_seed_ack(lang_iso: &str) -> &'static str {
    match lang_iso {
        "ru" => "Факты мира загружены. Попроси проверить любой фрагмент по ним или вставь текст для проверки.",
        "de" => "Weltfakten geladen. Bitte mich, eine Passage damit abzugleichen, oder füge Prosa zur Faktenprüfung ein.",
        "fr" => "Faits du monde chargés. Demande-moi de vérifier un passage par rapport à eux, ou colle un texte à vérifier.",
        "es" => "Hechos del mundo cargados. Pídeme verificar cualquier pasaje con ellos, o pega prosa para comprobar.",
        _ => "Loaded the world facts. Ask me to check any passage against them, or paste prose to fact-check.",
    }
}

/// 1.2.21+ — multilingual system prompt for the Facts scope + the
/// `Ctrl+B Shift+X` fact-check chord.  Frames the model as a
/// fact-analysis / fact-checking assistant grounded in the supplied
/// established facts.  Unknown codes fall back to English.
pub(crate) fn facts_scope_system_prompt(lang_iso: &str) -> &'static str {
    match lang_iso {
        "ru" => "Ты — внимательный помощник по проверке фактов в художественном произведении. \
В разговор включены установленные факты мира истории — климат, география, времена года, расстояния, хронология. \
Считай эти факты истиной. Когда автор спрашивает об отрывке, проверь его на противоречия с установленными фактами \
и точно назови, какой факт нарушен и как. Если отрывок согласуется — кратко скажи об этом. Не выдумывай новых фактов; \
если что-то не охвачено установленными фактами, скажи, что это не определено, а не угадывай.",
        "de" => "Du bist ein sorgfältiger Assistent für Faktenprüfung und Faktenanalyse für ein belletristisches Werk. \
Das Gespräch enthält die etablierten Fakten der Welt der Geschichte — Klima, Geografie, Jahreszeiten, Entfernungen, Chronologie. \
Behandle diese Fakten als Grundwahrheit. Wenn die Autorin nach einer Passage fragt, prüfe sie auf Widersprüche zu den \
etablierten Fakten und benenne genau, welcher Fakt wie verletzt wird. Ist eine Passage konsistent, sage es kurz. Erfinde \
keine neuen Fakten; was nicht von den etablierten Fakten abgedeckt ist, bezeichne als unbestimmt, statt zu raten.",
        "fr" => "Tu es un assistant méticuleux de vérification et d'analyse des faits pour une œuvre de fiction. \
La conversation inclut les faits établis du monde de l'histoire — climat, géographie, saisons, distances, chronologie. \
Considère ces faits comme la vérité de référence. Quand l'auteur t'interroge sur un passage, vérifie s'il contredit les \
faits établis et nomme précisément quel fait est violé et comment. Si un passage est cohérent, dis-le brièvement. \
N'invente jamais de faits ; si quelque chose n'est pas couvert par les faits établis, dis que c'est non spécifié plutôt que de deviner.",
        "es" => "Eres un asistente meticuloso de verificación y análisis de hechos para una obra de ficción. \
La conversación incluye los hechos establecidos del mundo de la historia — clima, geografía, estaciones, distancias, cronología. \
Trata esos hechos como verdad de referencia. Cuando el autor pregunte por un pasaje, compruébalo en busca de contradicciones \
con los hechos establecidos y nombra exactamente qué hecho se viola y cómo. Si un pasaje es coherente, dilo brevemente. \
No inventes hechos nuevos; si algo no está cubierto por los hechos establecidos, di que no está especificado en lugar de adivinar.",
        _ => "You are a meticulous fact-checking and facts-analysis assistant for a work of fiction. \
The conversation includes the established facts of the story's world — climate, geography, seasons, distances, chronology. \
Treat those facts as ground truth. When the author asks about a passage, check it for contradictions with the established \
facts and name exactly which fact is violated and how. If a passage is consistent, say so briefly. Never invent new facts; \
if something is not covered by the established facts, say it is unspecified rather than guessing.",
    }
}

/// 1.2.21+ — embedded fallback instruction for the `Ctrl+B Shift+X`
/// fact-check chord.  Pairs with [`facts_scope_system_prompt`] as the
/// system framing; the open paragraph + the established facts are
/// appended by the caller.  Five-language; English is the floor.
pub(crate) fn fact_check_default_prompt(lang_iso: &str) -> &'static str {
    match lang_iso {
        "ru" => "Проверь абзац ниже на соответствие установленным фактам мира из этого сообщения. \
Для КАЖДОГО утверждения в абзаце, которое ПРОТИВОРЕЧИТ установленному факту (места, расстояния, направления, климат, \
времена года, даты, длительности), выведи ОДНУ строку строго в формате:\n\
  claim | fact | detail\n\
где `claim` — точная фраза из текста, `fact` — нарушенный установленный факт, `detail` — объяснение в одну строку. \
Не переписывай абзац и не выводи ничего лишнего. Если противоречий нет — не выводи ничего.",
        "de" => "Prüfe den Absatz unten gegen die etablierten Weltfakten aus dieser Nachricht. \
Gib für JEDE Aussage im Absatz, die einem etablierten Fakt WIDERSPRICHT (Orte, Entfernungen, Richtungen, Klima, \
Jahreszeiten, Daten, Dauern), GENAU EINE Zeile im Format aus:\n\
  claim | fact | detail\n\
wobei `claim` die genaue Formulierung aus dem Text ist, `fact` der verletzte etablierte Fakt und `detail` eine einzeilige \
Erklärung. Schreibe den Absatz nicht um und gib nichts anderes aus. Gibt es keine Widersprüche, gib nichts aus.",
        "fr" => "Vérifie le paragraphe ci-dessous par rapport aux faits établis du monde fournis dans ce message. \
Pour CHAQUE affirmation du paragraphe qui CONTREDIT un fait établi (lieux, distances, directions, climat, saisons, dates, \
durées), produis UNE ligne au format exact :\n\
  claim | fact | detail\n\
où `claim` est la phrase exacte du texte, `fact` le fait établi violé, et `detail` une explication d'une ligne. \
Ne réécris pas le paragraphe et n'affiche rien d'autre. S'il n'y a aucune contradiction, n'affiche rien.",
        "es" => "Verifica el párrafo de abajo frente a los hechos establecidos del mundo incluidos en este mensaje. \
Para CADA afirmación del párrafo que CONTRADIGA un hecho establecido (lugares, distancias, direcciones, clima, estaciones, \
fechas, duraciones), produce UNA línea con el formato exacto:\n\
  claim | fact | detail\n\
donde `claim` es la frase exacta del texto, `fact` el hecho establecido violado y `detail` una explicación de una línea. \
No reescribas el párrafo ni muestres nada más. Si no hay contradicciones, no muestres nada.",
        _ => "Fact-check the paragraph below against the established world facts included in this message. \
For EACH claim in the paragraph that CONTRADICTS an established fact (places, distances, directions, climate, seasons, \
dates, durations), output ONE line in exactly this format:\n\
  claim | fact | detail\n\
where `claim` is the exact phrase from the prose, `fact` is the established fact it violates, and `detail` is a one-line \
explanation. Do not rewrite the paragraph and output nothing else. If nothing contradicts, output nothing.",
    }
}

/// translations of the same instructions tuned for native
/// grammatical idiom.  Unknown codes fall back to English
/// so the resolver always has a floor.  Same shape for the
/// other six embedded prompts below.
pub(crate) fn grammar_check_default_prompt(lang_iso: &str) -> &'static str {
    match lang_iso {
        "ru" => "Сделай корректорскую вычитку русского абзаца ниже. Проверь \
синтаксис, согласование, время и пунктуацию; отметь всё, что нарушает \
нормы современного русского языка. В тексте может быть разметка Typst — \
сохрани её дословно в исправленном варианте. После списка замечаний дай \
полностью исправленный абзац.",
        "es" => "Haz una corrección de estilo del párrafo en español que sigue. \
Revisa sintaxis, concordancia, tiempos verbales y puntuación; señala todo \
lo gramaticalmente incorrecto según la norma estándar del español. Puede \
haber marcado Typst — consérvalo literalmente en la versión corregida. \
Tras la lista de problemas, da el párrafo corregido por completo.",
        "de" => "Führe einen Korrektorat-Durchgang am folgenden deutschen Absatz \
durch. Prüfe Syntax, Kongruenz, Tempus und Interpunktion; markiere \
alles, was nach der Standard-Grammatik des Deutschen grammatisch falsch \
ist. Typst-Markup kann vorkommen — übernimm es wörtlich in den \
korrigierten Text. Liste die Probleme auf und gib danach den vollständig \
korrigierten Absatz.",
        "fr" => "Effectue une relecture de copy-edit sur le paragraphe français \
ci-dessous. Vérifie la syntaxe, l'accord, les temps et la ponctuation ; \
signale tout ce qui est grammaticalement incorrect au regard de la norme \
française standard. Du balisage Typst peut être présent — conserve-le \
tel quel dans toute version corrigée. Après la liste des problèmes, \
donne le paragraphe entièrement corrigé.",
        _ => "Run a copy-edit pass on the English paragraph below. Check \
syntax, agreement, tense, and punctuation; flag anything that's \
grammatically incorrect according to standard English grammar. Typst \
markup may be present — preserve it verbatim in any corrected output. \
After listing issues, give the fully corrected paragraph.",
    }
}

/// 1.2.6+ — embedded fallback for Ctrl+F12 explain-diagnostic.
/// 1.2.12+ Phase B — five-language variants.
pub(crate) fn explain_diagnostic_default_prompt(lang_iso: &str) -> &'static str {
    match lang_iso {
        "ru" => "Ниже показано диагностическое сообщение компилятора Typst \
вместе с фрагментом исходного кода. Объясни простым языком, что означает \
это сообщение, почему оно, скорее всего, возникло в данном контексте, и \
самое вероятное однострочное исправление. Если сообщение — ложное \
срабатывание (например, абзац ссылается на функцию, определённую в \
преамбуле книги, которая не видна изолированной компиляции), скажи об \
этом и переходи дальше. Ответ — короткий и конкретный.",
        "es" => "A continuación se muestra un diagnóstico del compilador Typst \
con el código fuente que lo rodea. Explica con palabras claras qué \
significa el diagnóstico, por qué probablemente se disparó en este \
contexto y la corrección más plausible de una sola línea. Si el \
diagnóstico es un falso positivo —por ejemplo, el párrafo usa una \
función definida en el preámbulo del libro que esta compilación aislada \
no ve—, dilo y sigue adelante. Mantén la respuesta breve y accionable.",
        "de" => "Unten siehst du eine Typst-Compiler-Meldung mitsamt umgebendem \
Quelltext. Erkläre in klarer Sprache, was die Meldung bedeutet, warum \
sie in diesem Kontext vermutlich ausgelöst wurde und welche einzeilige \
Korrektur am wahrscheinlichsten ist. Wenn es sich um einen Fehlalarm \
handelt — z. B. der Absatz nutzt eine im Buch-Präambel definierte \
Funktion, die diese isolierte Kompilierung nicht sieht — sag es und \
gehe weiter. Antwort knapp und umsetzbar halten.",
        "fr" => "Un diagnostic du compilateur Typst est présenté ci-dessous avec \
le code source qui l'entoure. Explique en français clair ce que signifie \
le diagnostic, pourquoi il s'est probablement déclenché dans ce \
contexte, et la correction d'une ligne la plus plausible. Si c'est un \
faux positif — par exemple, le paragraphe utilise une fonction définie \
dans le préambule du livre que cette compilation isolée ne voit pas — \
dis-le et passe à autre chose. Garde la réponse concise et actionnable.",
        _ => "A Typst compiler diagnostic is shown below with the surrounding \
source. Explain in plain English what the diagnostic means, why it \
likely fired in this context, and the most plausible one-line fix. If \
the diagnostic is a false positive — e.g. the paragraph references a \
function defined in the book's preamble that isn't visible to this \
isolated compile — say so and move on. Keep the answer tight and \
actionable.",
    }
}

/// 1.2.6+ — embedded fallback for F12 critique in editor mode.
/// 1.2.12+ Phase B — five-language variants.
pub(crate) fn critique_edit_default_prompt(lang_iso: &str) -> &'static str {
    match lang_iso {
        "ru" => "Прочти абзац ниже как черновик. Назови два-три самых слабых \
элемента: расплывчатые глаголы, абстрактные существительные там, где \
конкретное ударило бы сильнее, фразы, теряющие читателя, ритм, который \
сглаживается, утверждения, которые «плывут», образы, не оправдывающие \
своего места. Будь конкретен — цитируй именно тот оборот и предлагай \
более плотный вариант. НЕ переписывай весь абзац; критикуй его. Будь \
честным, но не разрушай текст.",
        "es" => "Lee el párrafo siguiente como un borrador. Señala los dos o \
tres elementos más débiles: verbos vagos, sustantivos abstractos donde \
lo concreto golpearía más fuerte, frases que pierden al lector, ritmo \
que se aplana, afirmaciones que titubean, imágenes que no se ganan su \
sitio. Sé específico: cita la frase exacta y propón una alternativa más \
apretada. NO reescribas el párrafo entero; critícalo. Sé honesto, no \
destructivo.",
        "de" => "Lies den folgenden Absatz wie einen Entwurf. Benenne die zwei \
oder drei schwächsten Stellen: vage Verben, abstrakte Substantive an \
Stellen, wo das Konkrete härter träfe, Sätze, die den Leser verlieren, \
Rhythmus, der erlahmt, Behauptungen, die wackeln, Bilder, die ihren \
Platz nicht verdienen. Sei konkret — zitiere die genaue Wendung und \
schlage eine straffere Alternative vor. Schreibe NICHT den ganzen \
Absatz neu; kritisiere ihn. Ehrlich, aber nicht zerstörerisch.",
        "fr" => "Lis le paragraphe ci-dessous comme un brouillon. Pointe les \
deux ou trois éléments les plus faibles : verbes vagues, noms abstraits \
là où le concret frapperait plus fort, phrases qui perdent le lecteur, \
rythme qui s'aplatit, affirmations qui vacillent, images qui ne \
méritent pas leur place. Sois précis — cite la formulation exacte et \
propose une alternative plus serrée. NE réécris PAS le paragraphe \
entier ; critique-le. Sois honnête sans être destructeur.",
        _ => "Read the paragraph below as a draft. Point out the weakest two \
or three elements: vague verbs, abstract nouns where the concrete would \
land harder, sentences that lose the reader, rhythm that flattens, \
claims that wobble, imagery that doesn't earn its place. Be specific — \
quote the exact phrase and propose a tighter alternative. Do NOT \
rewrite the whole paragraph; critique it. Be honest, not destructive.",
    }
}

/// 1.2.9+ — embedded fallback for the Ctrl+B Shift+T
/// AI-driven show-don't-tell scan.
/// 1.2.12+ Phase B — five-language variants.
pub(crate) fn show_dont_tell_default_prompt(lang_iso: &str) -> &'static str {
    match lang_iso {
        "ru" => "Прочти абзац ниже как черновик художественного текста и найди \
каждое место, где автор РАССКАЗЫВАЕТ, вместо того чтобы ПОКАЗЫВАТЬ. \
Рассказ = прямой ярлык эмоции или внутреннего состояния вместо того, \
чтобы дать поведению, чувственной детали или диалогу его проявить \
(«она злилась» — рассказ; «костяшки её пальцев побелели на стекле» — \
показ). По каждому случаю: (1) Процитируй точную фразу. (2) Назови, \
что именно рассказывается (эмоция / состояние). (3) Предложи один \
конкретный вариант показа — телесная деталь, чувственный штрих, \
действие или короткая реплика. Переписанный фрагмент той же длины, \
что и исходная строка, не абзац. Пропускай случаи, где рассказ \
оправдан (переходные фразы, краткое резюме, устоявшаяся внутренняя \
точка зрения в первом лице). Если абзац уже силён — скажи это прямо и \
остановись. Не разводи воду.",
        "es" => "Lee el párrafo de abajo como un borrador de ficción y busca \
cada lugar donde el autor está CONTANDO en lugar de MOSTRANDO. Contar \
= etiquetar directamente una emoción o estado interno en vez de dejar \
que la conducta, el detalle sensorial o el diálogo lo revelen («estaba \
enfadada» es contar; «los nudillos se le blanquearon contra el vaso» es \
mostrar). Para cada caso de contar: (1) Cita la frase exacta. (2) \
Nombra lo que se está contando (la emoción / el estado). (3) Propón un \
mostrar concreto — un gesto corporal, un detalle sensorial, una \
acción, o un fragmento de diálogo. La reescritura debe tener la misma \
longitud que la línea original, no un párrafo. Omite los casos donde \
contar es deliberadamente eficiente (transiciones, resumen, interioridad \
asentada en primera persona). Si el párrafo ya es fuerte, dilo \
claramente y para. No rellenes.",
        "de" => "Lies den folgenden Absatz als Belletristik-Entwurf und finde \
jede Stelle, an der der Autor BERICHTET statt ZU ZEIGEN. Berichten = \
eine Emotion oder einen inneren Zustand direkt benennen, statt Verhalten, \
Sinnesdetail oder Dialog ihn verraten zu lassen («sie war wütend» ist \
berichtet; «ihre Knöchel weißten sich um das Glas» ist gezeigt). Für \
jeden Berichts-Fall: (1) Zitiere die genaue Wendung. (2) Benenne, was \
berichtet wird (die Emotion / der Zustand). (3) Schlage eine konkrete \
Zeige-Umschreibung vor — eine Körpergeste, ein Sinnesdetail, eine \
Handlung oder ein Dialog-Fragment. Die Umschreibung soll dieselbe Länge \
haben wie die Berichts-Zeile, kein Absatz. Überspringe Fälle, in denen \
Berichten bewusst effizient ist (Überleitungen, Zusammenfassung, \
etablierte Innensicht in der ersten Person). Wenn der Absatz schon \
stark ist, sag es klar und hör auf. Kein Füller.",
        "fr" => "Lis le paragraphe ci-dessous comme un brouillon de fiction et \
repère chaque endroit où l'auteur RACONTE au lieu de MONTRER. Raconter \
= étiqueter directement une émotion ou un état interne au lieu de \
laisser le comportement, le détail sensoriel ou le dialogue le \
révéler («elle était en colère» = raconter ; «ses jointures \
blanchirent autour du verre» = montrer). Pour chaque cas de \
raconter : (1) Cite la formulation exacte. (2) Nomme ce qui est \
raconté (l'émotion / l'état). (3) Propose une réécriture-montrer \
concrète — un geste corporel, un détail sensoriel, une action, ou un \
fragment de dialogue. La réécriture doit faire la même longueur que \
la ligne d'origine, pas un paragraphe. Saute les cas où raconter est \
volontairement efficace (transitions, résumés, intériorité établie \
en première personne). Si le paragraphe est déjà solide, dis-le \
clairement et arrête. Pas de remplissage.",
        _ => "Read the paragraph below as a fiction draft and find every \
place where the writer is TELLING rather than SHOWING. Telling = \
directly labelling an emotion or internal state instead of letting \
behaviour, sensory detail, or dialogue reveal it (`she was angry` is \
telling; `her knuckles whitened around the glass` is showing). For \
each telling instance: (1) Quote the exact phrase. (2) Name what's \
being told (the emotion / state). (3) Propose one concrete show- \
rewrite — a body-language beat, a sensory detail, an action, or a \
fragment of dialogue. Keep the rewrite the same length as the telling \
line, not a paragraph. Skip cases where telling is deliberately \
efficient (transition lines, summary, established interiority in \
first-person POV). If the paragraph is already strong, say so plainly \
and stop. Don't pad.",
    }
}

/// 1.2.11+ — embedded fallback prompt for the
/// `Ctrl+B Shift+M` AI-driven sentence-rhythm rewrite.
/// 1.2.12+ Phase B — five-language variants.  Each
/// variant explicitly forbids translation in the
/// target language so the model rewrites in place
/// rather than localising mid-call.
pub(crate) fn sentence_rhythm_rewrite_default_prompt(lang_iso: &str) -> &'static str {
    match lang_iso {
        "ru" => "Перепиши русский абзац ниже так, чтобы сломать его монотонный \
синтаксический ритм. Чередуй короткие, резкие фразы с более длинными, \
чтобы у читательского уха была вариативность. Сохрани голос, тон, \
смысл, именованных персонажей, прямую речь, тире и абзацные разрывы. \
НЕ переводи; держи прозу на русском. НЕ резюмируй; переписывай строка \
за строкой.

Верни ТОЛЬКО переписанный абзац. Без вступления («Вот переписанный \
вариант:»), без комментариев, без markdown-заголовков, без списков, \
без объяснений. Чистая проза, готовая к вставке обратно в редактор.",
        "es" => "Reescribe el párrafo en español de abajo para romper su ritmo \
sintáctico monótono. Mezcla frases cortas y secas con otras más \
largas, de modo que el oído del lector tenga variedad. Conserva la voz, \
el tono, el sentido, los personajes nombrados, los diálogos entre \
comillas, las rayas y los saltos de párrafo. NO traduzcas; mantén la \
prosa en español. NO resumas; reescribe línea por línea.

Devuelve SÓLO el párrafo reescrito. Sin prefacio («Aquí está la \
reescritura:»), sin comentarios, sin encabezados markdown, sin viñetas, \
sin explicaciones. Prosa simple, lista para pegar en el editor.",
        "de" => "Schreibe den deutschen Absatz unten so um, dass sein \
monotoner Satzrhythmus aufgebrochen wird. Mische kurze, knappe Sätze \
mit längeren, sodass das Ohr des Lesers Abwechslung bekommt. Bewahre \
Stimme, Ton, Bedeutung, benannte Figuren, wörtliche Rede, Gedankenstriche \
und Absatzumbrüche. Übersetze NICHT; halte die Prosa auf Deutsch. \
Fasse NICHT zusammen; schreibe Zeile für Zeile um.

Gib NUR den umgeschriebenen Absatz zurück. Keine Einleitung (\"Hier ist \
die Umschrift:\"), keine Kommentare, keine Markdown-Überschriften, keine \
Aufzählungspunkte, keine Erklärungen. Reine Prosa, bereit zum \
Zurückeinfügen in den Editor.",
        "fr" => "Réécris le paragraphe français ci-dessous pour casser son \
rythme syntaxique monotone. Mêle des phrases courtes et nettes à \
d'autres plus longues, pour que l'oreille du lecteur ait de la \
variété. Conserve la voix, le ton, le sens, les personnages nommés, \
les dialogues entre guillemets, les tirets cadratins et les sauts de \
paragraphe. NE traduis PAS ; garde la prose en français. NE résume \
PAS ; réécris ligne à ligne.

Renvoie UNIQUEMENT le paragraphe réécrit. Pas de préface (« Voici la \
réécriture : »), pas de commentaire, pas de titres markdown, pas de \
puces, pas d'explication. Prose pure, prête à coller dans l'éditeur.",
        _ => "Rewrite the English paragraph below to break its monotonous \
sentence rhythm. Mix short, punchy sentences with longer ones so the \
reader's ear has variety to follow. Preserve voice, tone, meaning, \
named characters, quoted dialogue, em-dashes, and paragraph breaks. \
Do NOT translate; keep the prose in English. Do NOT summarise; \
rewrite line for line.

Return ONLY the rewritten paragraph. No preface (\"Here is the \
rewrite:\"), no commentary, no markdown headings, no bullet points, \
no explanation. Plain prose, ready to paste back into the editor.",
    }
}

/// 1.2.6+ — embedded fallback for F12 critique in split-edit mode.
/// 1.2.12+ Phase B — five-language variants.
pub(crate) fn critique_changes_default_prompt(lang_iso: &str) -> &'static str {
    match lang_iso {
        "ru" => "Ниже показаны две версии одного и того же абзаца: снимок \
`До` и текущий буфер `После`. Определи, что именно изменила правка \
(добавлено / удалено / переставлено), и оцени, каждое изменение — \
улучшение, регрессия или нейтрально. Цитируй именно те фразы, которые \
сдвинулись. В конце дай одно предложение, на чём должен \
сосредоточиться следующий проход правки.",
        "es" => "Abajo se muestran dos versiones del mismo párrafo: una \
instantánea `Antes` y el búfer actual `Después`. Identifica qué cambió \
la revisión (añadido / eliminado / reordenado) y evalúa si cada cambio \
es una mejora, una regresión, o neutro. Cita las frases concretas que \
se movieron. Termina con una sugerencia sobre en qué debería \
concentrarse la próxima pasada de revisión.",
        "de" => "Unten siehst du zwei Fassungen desselben Absatzes: einen \
`Vorher`-Schnappschuss und den aktuellen `Nachher`-Puffer. Stelle fest, \
was die Überarbeitung geändert hat (hinzugefügt / entfernt / umgestellt), \
und bewerte, ob jede Änderung eine Verbesserung, eine Verschlechterung \
oder neutral ist. Zitiere die konkreten Wendungen, die sich verschoben \
haben. Schließe mit einem Vorschlag dafür, worauf sich der nächste \
Überarbeitungsdurchlauf konzentrieren sollte.",
        "fr" => "Deux versions du même paragraphe sont présentées ci-dessous : \
un instantané `Avant` et le tampon courant `Après`. Identifie ce que \
la révision a changé (ajouté / retiré / réordonné), et évalue si \
chaque changement est une amélioration, une régression, ou neutre. \
Cite les formulations précises qui ont bougé. Termine par une \
suggestion sur ce qu'il faudrait viser à la prochaine passe de \
révision.",
        _ => "Two versions of the same paragraph are shown below: a `Before` \
snapshot and the current `After` buffer. Identify what the revision \
changed (added / removed / reordered), and evaluate whether each change \
is an improvement, a regression, or neutral. Quote the specific phrases \
that moved. End with one suggestion for what the next revision pass \
should focus on.",
    }
}

/// 1.2.12+ Phase D — embedded fallback for F12
/// critique when split-view is active with two
/// distinct paragraphs.  Sends both bodies and asks
/// for a comparative critique: where do they
/// converge, where do they diverge, which one lands
/// the beat better.  Particularly useful for
/// translation work (left = source, right =
/// translation: is the rendering accurate, does the
/// register match) and for draft comparison (left =
/// snapshot, right = current: which version is
/// stronger, line by line).
///
/// Five-language variants follow the same shape as
/// the other six embedded prompts; English is the
/// floor for unsupported codes.
pub(crate) fn critique_compare_default_prompt(lang_iso: &str) -> &'static str {
    match lang_iso {
        "ru" => "Ниже даны два абзаца — `Левый` и `Правый`.  Сравни их по
существу: что в них совпадает, что расходится, какой работает сильнее
и почему.  Обращай внимание на тон, ритм, точность образов, конкретику
глаголов и существительных.  Если это перевод (например, левый —
оригинал, правый — перевод), оцени, насколько перевод передаёт смысл,
голос и регистр.  Если это две черновых редакции, скажи, какая
интенсивнее и какие именно куски следующий проход правки должен
переносить из слабой в сильную.  Будь конкретен — цитируй точные
фразы.",
        "es" => "A continuación se muestran dos párrafos — `Izquierda` y
`Derecha`.  Compáralos en lo esencial: qué coincide, qué diverge, cuál
funciona mejor y por qué.  Presta atención al tono, al ritmo, a la
precisión de las imágenes, a la concreción de verbos y sustantivos.
Si se trata de una traducción (por ejemplo, izquierda = original,
derecha = traducción), evalúa si la traducción transmite el sentido,
la voz y el registro.  Si son dos borradores de revisión, indica
cuál tiene más fuerza y qué fragmentos concretos debería trasladar
la próxima pasada del débil al fuerte.  Sé específico — cita las
frases exactas.",
        "de" => "Unten siehst du zwei Absätze — `Links` und `Rechts`.
Vergleiche sie inhaltlich: was stimmt überein, was unterscheidet sich,
welcher trifft den Beat stärker und warum.  Achte auf Ton, Rhythmus,
Präzision der Bilder, Konkretheit der Verben und Substantive.  Wenn
es sich um eine Übersetzung handelt (z. B. links = Original, rechts =
Übersetzung), bewerte, ob die Übersetzung Sinn, Stimme und Register
trägt.  Wenn es zwei Entwürfe sind, sag, welcher kräftiger ist und
welche konkreten Stellen der nächste Überarbeitungsdurchlauf von der
schwächeren in die stärkere übernehmen sollte.  Sei konkret —
zitiere die genauen Wendungen.",
        "fr" => "Voici deux paragraphes — `Gauche` et `Droite`.  Compare-les
sur le fond : ce qui converge, ce qui diverge, lequel fonctionne plus
fort et pourquoi.  Sois attentif au ton, au rythme, à la précision
des images, au concret des verbes et des substantifs.  S'il s'agit
d'une traduction (par exemple, gauche = original, droite =
traduction), évalue si la traduction porte le sens, la voix et le
registre.  S'il s'agit de deux brouillons, dis lequel est plus
intense et quels fragments précis la prochaine passe de révision
doit reprendre du faible vers le fort.  Sois précis — cite les
formulations exactes.",
        _ => "Two paragraphs are shown below — `Left` and `Right`.  Compare \
them substantively: what overlaps, what diverges, which lands the \
beat harder and why.  Pay attention to tone, rhythm, precision of \
imagery, concreteness of verbs and nouns.  If this is a translation \
(e.g. left = source, right = translation), evaluate whether the \
translation carries the meaning, voice, and register.  If these are \
two drafts, say which one is stronger and which specific lines the \
next revision pass should carry from the weaker into the stronger.  \
Be specific — quote the exact phrases.",
    }
}

/// 1.2.6+ — embedded fallback for the timeline health
/// check (y / Y / Ctrl+Y inside Ctrl+V t).
/// 1.2.12+ Phase B — five-language variants.
pub(crate) fn timeline_health_default_prompt(lang_iso: &str) -> &'static str {
    match lang_iso {
        "ru" => "Ты проверяешь сюжетную хронологию ниже на внутреннюю \
согласованность. Относись к событиям как к фактам единого \
вымышленного мира; не выдумывай недостающие детали. Прочти контрольный \
список в конце и ответь по нему — будь конкретен, цитируй заголовки \
событий, предлагай конкретные исправления. Если хронология внутренне \
согласована — скажи об этом коротко, не разводя оговорок.",
        "es" => "Estás revisando la cronología narrativa que sigue para \
detectar incoherencias internas. Trata los eventos como hechos de un \
único mundo ficticio; no inventes detalles que falten. Lee la lista de \
verificación al final y responde a ella — sé específico, cita los \
títulos de eventos, y propón correcciones concretas. Si la cronología \
es internamente coherente, dilo brevemente en vez de rellenar con \
salvedades.",
        "de" => "Du prüfst die folgende Story-Zeitleiste auf innere \
Stimmigkeit. Behandle die Ereignisse als Fakten einer einzigen \
fiktionalen Welt; erfinde keine fehlenden Details. Lies die Prüfliste \
am Ende und reagiere darauf — sei konkret, zitiere Ereignistitel, und \
zeige greifbare Korrekturen auf. Wenn die Zeitleiste in sich \
stimmig ist, sag es kurz, statt mit Einschränkungen aufzufüllen.",
        "fr" => "Tu examines la chronologie narrative qui suit pour vérifier \
sa cohérence interne. Traite les événements comme des faits d'un \
unique monde fictif ; n'invente pas de détails manquants. Lis la \
liste de contrôle à la fin et réponds-y — sois précis, cite les \
titres d'événements, et propose des corrections concrètes. Si la \
chronologie est cohérente, dis-le brièvement plutôt que de remplir \
avec des réserves.",
        _ => "You are reviewing the story timeline that follows for internal \
consistency. Treat the events as facts about a single fictional world; \
do not invent missing detail. Read the audit checklist at the bottom \
and respond to it — be specific, quote event titles, and surface \
concrete fixes. If the timeline is internally coherent, say so briefly \
rather than padding with caveats.",
    }
}

/// System prompt for the F1 / "Help!" RAG flow. We force the model to
/// stick to the supplied excerpts so the help feature behaves like a
/// retrieval-grounded manual and not a general LLM chat — it should admit
/// ignorance rather than confabulate Inkhaven features.
pub(super) const HELP_SYSTEM_PROMPT: &str = "\
You are the Inkhaven help-manual assistant. Your job is to answer the \
user's question about Inkhaven (a Rust TUI literary editor for Typst \
books) using ONLY the Help excerpts the user provides below.

Rules:
- Use only the supplied excerpts. Do not invent commands, keybindings, \
  features, or file paths that are not present in the excerpts.
- Do not fall back on general LLM knowledge or assumptions about other \
  editors. If the excerpts do not answer the question, say so plainly \
  and suggest which area of the Help book might cover it.
- Quote keybindings, command names, and option labels verbatim from the \
  excerpts where useful.
- Be concise. Prefer short paragraphs and bulleted lists. Skip pleasantries.
- If multiple excerpts cover the topic, synthesise them; do not list them \
  as separate answers.
- Plain text only — no markdown headings beyond `#`/`-` lists.";

/// Inclusive on the top-left, exclusive on the bottom-right — matches
/// ratatui's Rect semantics where width/height are spans (the column at
/// `x + width` is one past the rect's last column).
/// 1.3.34+ — aggregate Output findings into per-node tree report-card badges: each
/// finding tied to a source paragraph tallies a count + worst severity onto that
/// paragraph and every ancestor (so a chapter shows the sum of its paragraphs).
fn compute_tree_badges(
    hierarchy: &crate::store::hierarchy::Hierarchy,
    msgs: &[crate::pane::output::Message],
) -> std::collections::HashMap<Uuid, (usize, crate::pane::output::Severity)> {
    use crate::pane::output::Severity;
    fn rank(s: Severity) -> u8 {
        match s {
            Severity::Progress => 0,
            Severity::Info => 1,
            Severity::Warning => 2,
            Severity::Contradiction => 3,
        }
    }
    let mut badges: std::collections::HashMap<Uuid, (usize, Severity)> =
        std::collections::HashMap::new();
    for m in msgs {
        let Some(pid) = m.source_paragraph_id else { continue };
        let mut cur = Some(pid);
        while let Some(id) = cur {
            let entry = badges.entry(id).or_insert((0, Severity::Progress));
            entry.0 += 1;
            if rank(m.severity) > rank(entry.1) {
                entry.1 = m.severity;
            }
            cur = hierarchy.get(id).and_then(|n| n.parent_id);
        }
    }
    badges
}

fn rect_contains(rect: Rect, col: u16, row: u16) -> bool {
    if rect.width == 0 || rect.height == 0 {
        return false;
    }
    col >= rect.x
        && col < rect.x.saturating_add(rect.width)
        && row >= rect.y
        && row < rect.y.saturating_add(rect.height)
}

pub(super) fn digit_count(n: usize) -> usize {
    let mut x = n.max(1);
    let mut d = 0;
    while x > 0 {
        d += 1;
        x /= 10;
    }
    d
}

/// REFLOW-1 — for the blank-line-delimited block of prose containing `cur_row`,
/// return `(start_row, end_row, rewrapped_text)` where the block's words are
/// re-wrapped (greedy word wrap) to `width` columns, newline-joined. Returns
/// `None` when the cursor is out of range or on a blank line (no paragraph).
/// Pure — unit-testable without an editor.
fn reflow_block(lines: &[String], cur_row: usize, width: usize) -> Option<(usize, usize, String)> {
    if cur_row >= lines.len() || lines[cur_row].trim().is_empty() {
        return None;
    }
    // Walk up/down over the contiguous non-blank run around the cursor.
    let start = (0..=cur_row)
        .rev()
        .take_while(|&r| !lines[r].trim().is_empty())
        .last()
        .unwrap_or(cur_row);
    let end = (cur_row..lines.len())
        .take_while(|&r| !lines[r].trim().is_empty())
        .last()
        .unwrap_or(cur_row);
    // Join the block's lines into one stream of words, then re-wrap. The reusable
    // greedy word-wrap collapses the original line breaks and re-breaks at `width`.
    let joined = lines[start..=end].join(" ");
    let wrapped = crate::tui::text_utils::wrap_words_or_chars(&joined, width).join("\n");
    Some((start, end, wrapped))
}

/// Allowlist of keystrokes that are non-mutating in the editor pane. Used to
/// gate the editor when an open paragraph lives inside the read-only Help
/// subtree. Anything not listed here is rejected with a status message.
fn is_read_only_safe_key(key: &KeyEvent) -> bool {
    use KeyCode::*;
    // Pure navigation / scrolling / selection — always safe.
    if matches!(
        key.code,
        Left | Right | Up | Down | Home | End | PageUp | PageDown | Esc | Tab | BackTab,
    ) {
        return true;
    }
    // F-keys: F3/F4/F6 are viewers (file picker, split toggle, snapshot
    // picker) — picking a file or snapshot WOULD mutate, but we gate the
    // actual replace in those flows. F5 (new snapshot) and Ctrl+F4 (accept
    // snapshot) mutate, so they're blocked here.
    if matches!(key.code, F(1) | F(3) | F(4) | F(6)) {
        // F4 with Ctrl is "accept snapshot" → block.
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        return !(matches!(key.code, F(4)) && ctrl);
    }
    // Alt+arrows and Alt+C are block-selection / block-copy — safe.
    if key.modifiers.contains(KeyModifiers::ALT) {
        if matches!(key.code, Left | Right | Up | Down) {
            return true;
        }
        if matches!(key.code, Char('c') | Char('C')) {
            return true;
        }
        return false;
    }
    // Ctrl combos: an explicit allowlist of read-safe operations.
    if key.modifiers.contains(KeyModifiers::CONTROL) {
        return matches!(
            key.code,
            Char('a') | Char('A')                // select all
            | Char('c') | Char('C')              // copy
            | Char('f') | Char('F')              // find
            | Char('x') | Char('X')              // repeat (next match)
            | Char('s') | Char('S')              // save (no-op + status)
            | Char('h') | Char('H')              // split-scroll up (only effective in split)
            | Char('j') | Char('J')              // split-scroll down
            | Char('q') | Char('Q')              // quit
            | Char('b') | Char('B')              // meta prefix
            | Char('t') | Char('T')              // focus Tree alias
            | Char('1') | Char('2') | Char('3') | Char('4') | Char('5') // focus jumps
            | Char('@') | Char('/')              // Ctrl+2 alternates / search focus
        );
    }
    false
}

pub(super) fn reverse_chip(fg: Color) -> Style {
    Style::default()
        .bg(fg)
        .fg(Color::Black)
        .add_modifier(Modifier::BOLD)
}

/// Extract the substring spanning `(start_row, start_col)..(end_row, end_col)`
/// from a slice of lines, where both ends are char-indexed. Used for pulling
/// the editor selection out for `{{selection}}` substitution.
fn slice_lines(lines: &[String], r1: usize, c1: usize, r2: usize, c2: usize) -> String {
    if r1 >= lines.len() {
        return String::new();
    }
    if r1 == r2 {
        let chars: Vec<char> = lines[r1].chars().collect();
        let s = c1.min(chars.len());
        let e = c2.min(chars.len());
        return chars[s..e].iter().collect();
    }
    let mut out = String::new();
    let first: String = lines[r1].chars().skip(c1).collect();
    out.push_str(&first);
    out.push('\n');
    for r in (r1 + 1)..r2 {
        if let Some(line) = lines.get(r) {
            out.push_str(line);
            out.push('\n');
        }
    }
    if let Some(last_line) = lines.get(r2) {
        let chars: Vec<char> = last_line.chars().collect();
        let e = c2.min(chars.len());
        out.extend(chars[..e].iter());
    }
    out
}

#[cfg(test)]
mod tests_node_lang {
    use super::*;
    use crate::store::node::{Node, NodeKind};
    use chrono::Utc;
    use uuid::Uuid;

    fn paragraph_with_tags(tags: Vec<String>) -> Node {
        Node {
            id: Uuid::new_v4(),
            kind: NodeKind::Paragraph,
            title: "test".into(),
            slug: "test".into(),
            path: Vec::new(),
            parent_id: None,
            order: 0,
            file: None,
            word_count: 0,
            modified_at: Utc::now(),
            protected: false,
            system_tag: None,
            image_ext: None,
            image_caption: None,
            image_alt: None,
            content_type: None,
            status: None,
            target_words: None,
            target_hit_at_status: None,
            linked_paragraphs: Vec::new(),
            bookmark: false,
            tags,
            ai_memory: Vec::new(),
            event: None,
        }
    }

    #[test]
    fn node_lang_tag_extracts_code() {
        let n = paragraph_with_tags(vec!["lang:ru".into(), "draft".into()]);
        assert_eq!(node_lang_tag(&n), Some("ru".into()));
    }

    #[test]
    fn node_lang_tag_case_insensitive() {
        // Tag preserves case on save, but the lookup
        // lowercases both sides.
        let n = paragraph_with_tags(vec!["LANG:RU".into()]);
        assert_eq!(node_lang_tag(&n), Some("ru".into()));
    }

    #[test]
    fn node_lang_tag_absent_returns_none() {
        let n = paragraph_with_tags(vec!["draft".into(), "wip".into()]);
        assert_eq!(node_lang_tag(&n), None);
    }

    #[test]
    fn node_lang_tag_ignores_empty_value() {
        // `lang:` with no code → not a meaningful tag; treat
        // as untagged so the resolver falls through to Pass 2.
        let n = paragraph_with_tags(vec!["lang:".into()]);
        assert_eq!(node_lang_tag(&n), None);
    }

    #[test]
    fn node_lang_matches_strict_same_language() {
        let n = paragraph_with_tags(vec!["lang:ru".into()]);
        assert!(node_lang_matches(&n, Some("ru")));
        assert!(!node_lang_matches(&n, Some("en")));
    }

    #[test]
    fn node_lang_matches_untagged_pass_skips_tagged_nodes() {
        // Pass 2 (lang_filter = None) must only match nodes
        // that have NO lang:* tag.  A node tagged `lang:ru`
        // is a Pass 1 / Pass 3 hit, never Pass 2.
        let n = paragraph_with_tags(vec!["lang:ru".into()]);
        assert!(!node_lang_matches(&n, None));
    }

    #[test]
    fn node_lang_matches_untagged_pass_matches_untagged_nodes() {
        let n = paragraph_with_tags(vec!["draft".into()]);
        assert!(node_lang_matches(&n, None));
    }
}

#[cfg(test)]
mod tests_split_view {
    use super::*;

    /// 1.2.12+ Phase A — the binding-table audit.
    /// Locks the guarantee that F4 and Ctrl+F4 keep
    /// their existing meanings.  If a future commit
    /// rebinds either, this test fails loud.
    #[test]
    fn existing_f4_and_ctrl_f4_bindings_remain_untouched() {
        use crate::tui::keybind;
        let table = keybind::KeyBindings::defaults();
        // F4 plain → ToggleSplit in editor scope.
        let f4 = table
            .top_level
            .iter()
            .find(|e| {
                e.chord.code == crossterm::event::KeyCode::F(4)
                    && e.chord.modifiers == crossterm::event::KeyModifiers::NONE
            })
            .expect("F4 must still bind to something");
        assert!(
            matches!(f4.action, keybind::Action::ToggleSplit),
            "F4 must still mean ToggleSplit; Phase A may not rebind it",
        );
        // Ctrl+F4 → AcceptSplitSnapshot.
        let ctrl_f4 = table
            .top_level
            .iter()
            .find(|e| {
                e.chord.code == crossterm::event::KeyCode::F(4)
                    && e.chord.modifiers == crossterm::event::KeyModifiers::CONTROL
            })
            .expect("Ctrl+F4 must still bind to something");
        assert!(
            matches!(ctrl_f4.action, keybind::Action::AcceptSplitSnapshot),
            "Ctrl+F4 must still mean AcceptSplitSnapshot",
        );
        // Shift+F4 → ToggleSplitView (the new chord).
        let shift_f4 = table
            .top_level
            .iter()
            .find(|e| {
                e.chord.code == crossterm::event::KeyCode::F(4)
                    && e.chord.modifiers == crossterm::event::KeyModifiers::SHIFT
            })
            .expect("Shift+F4 must bind to ToggleSplitView");
        assert!(
            matches!(shift_f4.action, keybind::Action::ToggleSplitView),
            "Shift+F4 must map to ToggleSplitView",
        );
    }

    /// 1.2.12+ Phase A — `PaneTarget::default()` is
    /// `Primary`.  Locks the contract that picker
    /// callers default to the primary slot when no
    /// explicit target is set.
    #[test]
    fn pane_target_defaults_to_primary() {
        assert_eq!(PaneTarget::default(), PaneTarget::Primary);
    }

    /// 1.2.12+ Phase B — Shift+Enter chord is
    /// detected from the SHIFT modifier on a KeyEvent.
    /// The picker handlers extract this *before*
    /// destructuring the modal so the routing
    /// decision survives the modal re-borrow.
    /// Locks the contract that the SHIFT modifier
    /// flag is what drives pin_to_secondary, not
    /// any per-picker custom chord.
    #[test]
    fn shift_modifier_drives_pin_to_secondary() {
        use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
        let plain = KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE);
        let shifted = KeyEvent::new(KeyCode::Enter, KeyModifiers::SHIFT);
        assert!(!plain.modifiers.contains(KeyModifiers::SHIFT));
        assert!(shifted.modifiers.contains(KeyModifiers::SHIFT));
    }

    /// 1.2.12+ Phase C — locks the Tab dispatch
    /// contract.  The Tab handler at
    /// `app.rs:3091` flips `secondary_focused`
    /// when the secondary slot is populated; this
    /// test exercises the boolean toggle itself in
    /// isolation so a future refactor that changes
    /// the Tab dispatch can't silently break the
    /// invariant.
    #[test]
    fn tab_swap_toggles_secondary_focused_flag() {
        // The contract: starting from
        // `secondary_focused = false`, one toggle
        // flips to true; a second toggle flips
        // back.  The Tab handler in `handle_key`
        // expresses this as
        // `secondary_focused = !secondary_focused`.
        let mut focused = false;
        focused = !focused;
        assert!(focused, "first Tab swaps to right editor");
        focused = !focused;
        assert!(!focused, "second Tab swaps back to left editor");
    }

    /// 1.2.12+ Phase C — the autosave loop walks
    /// both `opened` and `secondary` slots; this
    /// already shipped in 1.2.4 with similar-mode
    /// (`tick_autosave` at app.rs:2161-2200).
    /// Phase A inherits that behaviour for split-
    /// view since both layouts use the same
    /// secondary slot.  This test guards against a
    /// future refactor that drops the secondary
    /// branch of the autosave by asserting the
    /// surface continues to expose `save_doc` as
    /// the shared save path.
    #[test]
    fn save_doc_is_callable_against_secondary_slot() {
        // Compile-time check: `save_doc` exists with
        // the right signature.  Anyone removing it
        // would break this assertion at compile
        // time, surfacing the autosave regression
        // before the binary ships.
        fn _type_check_save_doc<T>(_: T)
        where
            T: for<'a> Fn(&'a mut App, &'a mut OpenedDoc) -> Result<(), String>,
        {
        }
        _type_check_save_doc(|app: &mut App, doc: &mut OpenedDoc| {
            app.save_doc(doc)
        });
    }

    /// 1.2.12+ Phase D — locks the contract that the
    /// new `critique-compare` embedded prompt has a
    /// five-language match (the same shape as every
    /// other embedded prompt in 1.2.11+).
    #[test]
    fn critique_compare_default_prompt_covers_five_languages() {
        // Each language returns a distinct, non-empty
        // body.  English is the fallback for unknown
        // codes, so an unsupported code maps to the
        // same body as "en".
        let en = super::critique_compare_default_prompt("en");
        let ru = super::critique_compare_default_prompt("ru");
        let es = super::critique_compare_default_prompt("es");
        let de = super::critique_compare_default_prompt("de");
        let fr = super::critique_compare_default_prompt("fr");
        let unknown = super::critique_compare_default_prompt("klingon");
        // Every variant has content.
        for body in [en, ru, es, de, fr] {
            assert!(
                body.trim().len() > 80,
                "critique_compare body suspiciously short: {body:?}",
            );
        }
        // The five known variants are pairwise distinct
        // (translation, not pass-through).
        let bodies = [en, ru, es, de, fr];
        for i in 0..bodies.len() {
            for j in (i + 1)..bodies.len() {
                assert_ne!(
                    bodies[i], bodies[j],
                    "critique_compare bodies at indices {i} and {j} are identical — translation missed?",
                );
            }
        }
        // Unknown codes fall back to English.
        assert_eq!(unknown, en);
    }

    /// 1.2.21+ — the Facts-scope system prompt (and the seed
    /// intro / ack) follow the same five-language contract as
    /// every other embedded prompt.
    #[test]
    fn facts_scope_prompts_cover_five_languages() {
        for f in [
            super::facts_scope_system_prompt
                as fn(&str) -> &'static str,
            super::facts_seed_intro,
            super::facts_seed_ack,
            super::fact_check_default_prompt,
        ] {
            let en = f("en");
            let variants = [f("en"), f("ru"), f("de"), f("fr"), f("es")];
            for body in variants {
                assert!(!body.trim().is_empty(), "empty facts prompt body");
            }
            for i in 0..variants.len() {
                for j in (i + 1)..variants.len() {
                    assert_ne!(
                        variants[i], variants[j],
                        "facts prompt variants {i}/{j} identical — translation missed?",
                    );
                }
            }
            // Unknown codes fall back to English.
            assert_eq!(f("klingon"), en);
        }
        // The system prompt names the fact-check job explicitly.
        let sys = super::facts_scope_system_prompt("en").to_lowercase();
        assert!(sys.contains("fact"));
        assert!(sys.contains("ground truth"));
    }
}

#[cfg(test)]
mod tests_leaf_cycle {
    use super::next_leaf_type;
    use crate::store::node::NodeKind;

    #[test]
    fn morph_cycle_includes_jinja_and_loops() {
        // STRUCT-1 — the t/T morph cycle must pass through the jinja rung.
        // Single source of truth (next_leaf_type) drives both the single and
        // bulk paths, so this guards against the two ladders drifting again.
        let steps = [
            (NodeKind::Paragraph, None, (NodeKind::Paragraph, Some("hjson"))),
            (NodeKind::Paragraph, Some("hjson"), (NodeKind::Paragraph, Some("jinja"))),
            (NodeKind::Paragraph, Some("jinja"), (NodeKind::Script, Some("bund"))),
            (NodeKind::Script, Some("bund"), (NodeKind::Paragraph, None)),
        ];
        for (kind, ct, (want_kind, want_ct)) in steps {
            let (k, c, _label) = next_leaf_type(kind, ct).expect("cyclable leaf");
            assert_eq!((k, c), (want_kind, want_ct), "from {kind:?}/{ct:?}");
        }
        // Explicit-typst behaves like None (start of the cycle).
        assert_eq!(
            next_leaf_type(NodeKind::Paragraph, Some("typst")).map(|t| (t.0, t.1)),
            Some((NodeKind::Paragraph, Some("hjson")))
        );
        // Non-leaf kinds don't cycle.
        assert!(next_leaf_type(NodeKind::Book, None).is_none());
        assert!(next_leaf_type(NodeKind::Chapter, None).is_none());
    }
}

#[cfg(test)]
mod tests_structural {
    use super::{
        STRUCTURAL_TYPES, is_structural_nonprose, is_structural_paragraph, structural_glyph,
    };
    use crate::store::node::Node;

    fn para_with_tags(tags: &[&str]) -> Node {
        serde_json::from_value(serde_json::json!({
            "id": uuid::Uuid::nil(), "kind": "paragraph", "title": "p", "slug": "p",
            "path": [], "parent_id": null, "order": 1, "file": null,
            "modified_at": "2026-01-01T00:00:00Z",
            "tags": tags,
        }))
        .expect("test node")
    }

    #[test]
    fn structural_glyph_maps_known_tags_only() {
        // STRUCT-2 — every table tag resolves to its glyph; prose / unknown
        // para: tags fall through to None (caller uses ¶).
        for (tag, glyph, _label, _seed) in STRUCTURAL_TYPES {
            assert_eq!(structural_glyph(&para_with_tags(&[tag])), Some(*glyph), "{tag}");
        }
        assert_eq!(structural_glyph(&para_with_tags(&[])), None);
        assert_eq!(structural_glyph(&para_with_tags(&["draft"])), None);
        assert_eq!(structural_glyph(&para_with_tags(&["para:unknown"])), None);
        // A user tag alongside the structural one still resolves.
        assert_eq!(
            structural_glyph(&para_with_tags(&["draft", "para:math"])),
            Some("∫ ")
        );
    }

    #[test]
    fn structural_gates_split_prose_from_nonprose() {
        // is_structural_paragraph = any para:* tag; the companions' skip gate
        // (is_structural_nonprose) excludes everything EXCEPT para:procedure.
        assert!(!is_structural_paragraph(&para_with_tags(&[])));
        assert!(!is_structural_paragraph(&para_with_tags(&["draft"])));
        assert!(is_structural_paragraph(&para_with_tags(&["para:code"])));
        assert!(is_structural_paragraph(&para_with_tags(&["para:procedure"])));

        // Non-prose structural → companions skip.
        assert!(is_structural_nonprose(&para_with_tags(&["para:code"])));
        assert!(is_structural_nonprose(&para_with_tags(&["para:math"])));
        // Procedure is prose → companions still run (excluded from the skip).
        assert!(!is_structural_nonprose(&para_with_tags(&["para:procedure"])));
        // Plain prose → not skipped.
        assert!(!is_structural_nonprose(&para_with_tags(&["draft"])));
    }

    #[test]
    fn structural_table_is_well_formed() {
        // All tags para:-prefixed + unique; every glyph carries a trailing space
        // (matches the tree's "¶ " / "❴ " convention).
        let mut seen = std::collections::HashSet::new();
        for (tag, glyph, label, seed) in STRUCTURAL_TYPES {
            assert!(tag.starts_with("para:"), "{tag}");
            assert!(seen.insert(*tag), "duplicate {tag}");
            assert!(glyph.ends_with(' '), "glyph for {tag} needs trailing space");
            assert!(!label.is_empty() && !seed.is_empty(), "{tag}");
        }
        assert_eq!(STRUCTURAL_TYPES.len(), 8);
    }
}

#[cfg(test)]
mod tests_tree_badges {
    use super::compute_tree_badges;
    use crate::pane::output::{Lifetime, Message, Severity};
    use crate::store::hierarchy::Hierarchy;
    use crate::store::node::Node;
    use uuid::Uuid;

    fn node(id: Uuid, kind: &str, slug: &str, parent: Option<Uuid>) -> Node {
        serde_json::from_value(serde_json::json!({
            "id": id, "kind": kind, "title": slug, "slug": slug,
            "path": [], "parent_id": parent, "order": 1, "file": null,
            "modified_at": "2026-01-01T00:00:00Z",
        }))
        .expect("test node")
    }

    fn msg(sev: Severity, para: Uuid) -> Message {
        Message::new("fact_check_warning", sev, Lifetime::UntilActedOn, serde_json::json!({}))
            .with_source_paragraph(para)
    }

    #[test]
    fn findings_aggregate_up_to_ancestors_with_worst_severity() {
        let book = Uuid::now_v7();
        let chapter = Uuid::now_v7();
        let p1 = Uuid::now_v7();
        let p2 = Uuid::now_v7();
        let h = Hierarchy::from_nodes_for_test(vec![
            node(book, "book", "velmaron", None),
            node(chapter, "chapter", "ch1", Some(book)),
            node(p1, "paragraph", "p1", Some(chapter)),
            node(p2, "paragraph", "p2", Some(chapter)),
        ]);
        // p1: one Warning + one Contradiction; p2: one Info.
        let msgs = vec![
            msg(Severity::Warning, p1),
            msg(Severity::Contradiction, p1),
            msg(Severity::Info, p2),
        ];
        let badges = compute_tree_badges(&h, &msgs);
        // Paragraph-level counts + worst severity.
        assert_eq!(badges[&p1], (2, Severity::Contradiction));
        assert_eq!(badges[&p2], (1, Severity::Info));
        // Chapter aggregates all three; worst is the contradiction.
        assert_eq!(badges[&chapter], (3, Severity::Contradiction));
        // Book aggregates the whole subtree too.
        assert_eq!(badges[&book], (3, Severity::Contradiction));
    }

    #[test]
    fn messages_without_a_source_paragraph_are_ignored() {
        let h = Hierarchy::from_nodes_for_test(vec![node(Uuid::now_v7(), "book", "b", None)]);
        let m = Message::new("bund_print", Severity::Info, Lifetime::UntilActedOn, serde_json::json!({}));
        assert!(compute_tree_badges(&h, &[m]).is_empty());
    }

    // COMPANIONS-1 — the badge computation is kind-agnostic, so Inner Editor's
    // observations (like every companion's findings) already badge the tree.
    // Pin that so a future kind filter can't silently drop them.
    #[test]
    fn inner_editor_observations_badge_the_tree() {
        use crate::pane::output::kinds;
        let book = Uuid::now_v7();
        let chapter = Uuid::now_v7();
        let p1 = Uuid::now_v7();
        let h = Hierarchy::from_nodes_for_test(vec![
            node(book, "book", "b", None),
            node(chapter, "chapter", "ch1", Some(book)),
            node(p1, "paragraph", "p1", Some(chapter)),
        ]);
        let editor = Message::new(
            kinds::INNER_EDITOR_OBSERVATION,
            Severity::Warning,
            Lifetime::UntilActedOn,
            serde_json::json!({}),
        )
        .with_source_paragraph(p1);
        let badges = compute_tree_badges(&h, &[editor]);
        assert_eq!(badges[&p1], (1, Severity::Warning));
        assert_eq!(badges[&chapter], (1, Severity::Warning));
        assert_eq!(badges[&book], (1, Severity::Warning));
    }
}

#[cfg(test)]
mod tests_reflow {
    use super::reflow_block;

    fn lines(v: &[&str]) -> Vec<String> {
        v.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn single_long_line_wraps_to_width() {
        let l = lines(&["the quick brown fox jumps over the lazy dog"]);
        let (start, end, out) = reflow_block(&l, 0, 20).unwrap();
        assert_eq!((start, end), (0, 0));
        // Every produced line fits the width; the text round-trips word-for-word.
        assert!(out.lines().all(|ln| ln.chars().count() <= 20));
        assert_eq!(out.split_whitespace().collect::<Vec<_>>(), l[0].split_whitespace().collect::<Vec<_>>());
        assert!(out.contains('\n')); // it actually wrapped
    }

    #[test]
    fn rewraps_a_hardwrapped_block_within_blank_lines() {
        let l = lines(&["intro para", "", "one two", "three four", "five", "", "tail"]);
        // Cursor on row 3 (inside the middle block rows 2..=4).
        let (start, end, out) = reflow_block(&l, 3, 40).unwrap();
        assert_eq!((start, end), (2, 4));
        assert_eq!(out, "one two three four five"); // collapsed to one line at width 40
    }

    #[test]
    fn blank_line_or_out_of_range_is_none() {
        let l = lines(&["a", "", "b"]);
        assert!(reflow_block(&l, 1, 40).is_none()); // on the blank line
        assert!(reflow_block(&l, 9, 40).is_none()); // out of range
    }
}

#[cfg(test)]
mod tests_snippet_include {
    use super::*;

    #[test]
    fn detect_include_inside_snippet_path() {
        let line = "#include \"../../snippets/warn.typ\"";
        // Cursor inside the path (on "warn").
        let col = line.chars().take_while(|&c| c != 'w').count();
        let ctx = detect_include_context(line, col).expect("inside the include string");
        assert_eq!(ctx.snippet_slug.as_deref(), Some("warn"));
        // The quote span covers `"../../snippets/warn.typ"` exactly.
        assert_eq!(ctx.quote_start_col, "#include ".chars().count());
        assert_eq!(ctx.quote_end_col, line.chars().count());
    }

    #[test]
    fn detect_include_outside_string_is_none() {
        let line = "#include \"../snippets/x.typ\" trailing text";
        // Cursor in the trailing text, after the closing quote.
        let col = line.chars().count() - 2;
        assert!(detect_include_context(line, col).is_none());
        // No #include at all.
        assert!(detect_include_context("just prose here", 4).is_none());
    }

    #[test]
    fn detect_include_non_snippet_has_no_slug() {
        let line = "#include \"globals.typ\"";
        let col = line.chars().take_while(|&c| c != 'g').count();
        let ctx = detect_include_context(line, col).expect("inside the string");
        assert!(ctx.snippet_slug.is_none(), "globals.typ is not a snippet");
    }
}
